{"content":"#!/usr/bin/env python
"""Verify the TcRange.iter_tcs() fix without requiring full pptx installation."""

import sys
sys.path.insert(0, 'src')

# Mock the dependencies
class MockModule:
    def __getattr__(self, name):
        return MockModule()

    def __call__(self, *args, **kwargs):
        return MockModule()

sys.modules['lxml'] = MockModule()
sys.modules['lxml.etree'] = MockModule()

# Now we can import the fixed code
from pptx.oxml.table import TcRange

# Create mock objects to test the iteration logic
class MockTc:
    def __init__(self, row_idx, col_idx):
        self.row_idx = row_idx
        self.col_idx = col_idx
        self.tbl = None

    def __repr__(self):
        return f"MockTc(row={self.row_idx}, col={self.col_idx})"

class MockTr:
    def __init__(self, row_idx, num_cols):
        self.tc_lst = [MockTc(row_idx, col_idx) for col_idx in range(num_cols)]

class MockTbl:
    def __init__(self, num_rows, num_cols):
        self.tr_lst = [MockTr(row_idx, num_cols) for row_idx in range(num_rows)]

# Create a 3x3 table
tbl = MockTbl(3, 3)

# Set up the table references
for tr in tbl.tr_lst:
    for tc in tr.tc_lst:
        tc.tbl = tbl

# Test case: range from (0,0) to (1,2) - should be 2 rows, 3 columns
tc_top_left = tbl.tr_lst[0].tc_lst[0]
tc_bottom_right = tbl.tr_lst[1].tc_lst[2]

tc_range = TcRange(tc_top_left, tc_bottom_right)
cells = list(tc_range.iter_tcs())

print("Test: TcRange from (0,0) to (1,2)")
print(f"Expected: 6 cells in left-to-right, top-to-bottom order")
print(f"Actual: {len(cells)} cells")
print("\nCell order:")
for i, cell in enumerate(cells):
    print(f"  {i+1}. row={cell.row_idx}, col={cell.col_idx}")

# Verify the order is correct
expected_order = [
    (0, 0), (0, 1), (0, 2),  # First row, left to right
    (1, 0), (1, 1), (1, 2),  # Second row, left to right
]

actual_order = [(cell.row_idx, cell.col_idx) for cell in cells]

if actual_order == expected_order:
    print("\n✓ PASS: Cells are in correct left-to-right, top-to-bottom order")
    sys.exit(0)
else:
    print("\n✗ FAIL: Cells are NOT in correct order")
    print(f"Expected: {expected_order}")
    print(f"Actual:   {actual_order}")
    sys.exit(1)
